def _coupon_inputs(block, x, bridge):
    axial = bridge.sum(axis=1)
    past = block['past_channel_raw'] @ axial[1:] + axial[0]
    hold = block['hold_channel_raw'] @ axial[1:] + axial[0]
    return (past, hold, np.column_stack((np.ones(len(x)), x)))

def _fit(coupons, dt, times, curve_obs, rate_obs):
    from scipy.optimize import least_squares
    curve_ok = np.isfinite(curve_obs.ravel())
    rate_ok = np.isfinite(rate_obs)
    curve_y = curve_obs.ravel()[curve_ok]
    rate_y = rate_obs[rate_ok]
    y = np.r_[curve_y, rate_y]
    ncurve = len(curve_y)

    def build(taus):
        (curve, rate) = _design(taus, coupons, dt, times)
        return np.vstack((curve.reshape(-1, 7)[curve_ok], rate[rate_ok]))

    def decode(p):
        fast = np.exp(p[0])
        return np.array((fast, fast + (25.0 - fast) * p[1]))

    def encode(fast, slow):
        return np.array((np.log(fast), (slow - fast) / (25.0 - fast)))
    bounds = ([np.log(0.050001), 1e-06], [np.log(24.99), 1 - 1e-06])

    def profile(p):
        a = build(decode(p))
        return a @ np.linalg.lstsq(a, y, rcond=None)[0] - y
    grid = [encode(f, s) for f in (0.08, 0.18, 0.4, 0.8, 1.6, 3.2) for s in (0.3, 0.65, 1.3, 2.6, 5.2, 10.4, 21.0) if f < s]
    starts = sorted(grid, key=lambda p: np.linalg.norm(profile(p)))[:3]
    ordinary = min((least_squares(profile, p, bounds=bounds, max_nfev=100) for p in starts), key=lambda r: r.cost)
    a = build(decode(ordinary.x))
    theta = np.linalg.lstsq(a, y, rcond=None)[0]

    def mad(r):
        return max(1e-06, 1.4826 * np.median(np.abs(r - np.median(r))))

    def scale(r):
        return np.r_[np.full(ncurve, mad(r[:ncurve])), np.full(len(rate_y), mad(r[ncurve:]))]

    def robust(p, sigma, loss, f_scale):
        return least_squares(lambda v: (build(decode(v[:2])) @ v[2:] - y) / sigma, p, bounds=(np.r_[bounds[0], [-np.inf] * 7], np.r_[bounds[1], [np.inf] * 7]), loss=loss, f_scale=f_scale, x_scale='jac', max_nfev=200)
    sigma = scale(ordinary.fun)
    first = robust(np.r_[ordinary.x, theta], sigma, 'soft_l1', 1.5)
    sigma = scale(first.fun * sigma)
    result = robust(first.x, sigma, 'cauchy', 2.5)
    return (decode(result.x[:2]), result.x[2:])

def _chamber(taus, theta, hold, covariates, times):
    relaxation = -np.expm1(-times[:, None] / taus)
    weights = np.array([0.25514561, 0.23475018, 0.51010421])
    kernel = weights[0] * times + relaxation @ (weights[1:] * taus)
    drift = covariates @ theta[2:]
    return (hold[:, None] * (relaxation @ theta[:2]) + drift[:, None] * kernel, hold * np.sum(theta[:2] / taus) + drift)
